    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg:
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg:
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        if (r, c) in seen or grid[r][c] != bg:
            continue
        seen.add((r, c))
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen:
                stack.append((nr, nc))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r, c) not in seen:
                out[r][c] = 4
    return out
